<?php

declare(strict_types=1);

namespace Seampact\Ir\Write;

/**
 * The one line every generated file with comment syntax starts with (ADR 0015 "The generated header"): the target
 * package, its version and the api, never a timestamp, a path or a hash. A PHP file keeps its `<?php` open tag
 * first, so the header is the line after it; JSON has no comment syntax and the manifest covers it.
 */
final class GeneratedHeader
{
    private const PHP_OPEN_TAG_LINE = "<?php\n";

    private const NO_COMMENT = '';

    // The extensions the PHP targets emit, each with the line comment that carries the header.
    private const LINE_COMMENT_BY_EXTENSION = ['.php' => '//', '.yaml' => '#', '.json' => self::NO_COMMENT];

    private const REPORT_FIX = "Report this to the target's maintainers: the writer must learn the extension before a target emits it.";

    private function __construct()
    {
    }

    public static function line(string $generator, string $version, string $api): string
    {
        return "Generated by {$generator} {$version} from api \"{$api}\". Do not edit.";
    }

    /**
     * Each file with the header added, or one refusal per file the writer cannot head.
     *
     * @param list<GeneratedFile> $files
     * @return list<GeneratedFile>|list<WriterRefusal>
     */
    public static function added(array $files, string $generator, string $version, string $api): array
    {
        $line = self::line($generator, $version, $api);
        $finished = [];
        $refusals = [];

        foreach ($files as $file) {
            $headed = self::headed($file, $line);
            if ($headed instanceof WriterRefusal) {
                $refusals[] = $headed;
            } else {
                $finished[] = $headed;
            }
        }

        return $refusals === [] ? $finished : $refusals;
    }

    private static function headed(GeneratedFile $file, string $line): GeneratedFile|WriterRefusal
    {
        $extension = self::extensionOf($file->path);
        $comment = self::LINE_COMMENT_BY_EXTENSION[$extension] ?? null;

        if ($comment === null) {
            $known = implode(', ', array_keys(self::LINE_COMMENT_BY_EXTENSION));

            return new WriterRefusal(
                'file.extension.unsupported',
                "The target generated '{$file->path}', whose extension is not one the writer knows ({$known}).",
                self::REPORT_FIX,
            );
        }

        if ($comment === self::NO_COMMENT) {
            return $file;
        }

        if ($extension !== '.php') {
            return new GeneratedFile($file->path, "{$comment} {$line}\n{$file->contents}");
        }

        $contents = str_replace("\r\n", "\n", $file->contents);
        if (!str_starts_with($contents, self::PHP_OPEN_TAG_LINE)) {
            return new WriterRefusal(
                'file.php.open-tag',
                "The target generated '{$file->path}', which does not start with `<?php` on a line of its own.",
                "Report this to the target's maintainers: a generated PHP file starts with its open tag line.",
            );
        }

        return new GeneratedFile($file->path, self::PHP_OPEN_TAG_LINE . "{$comment} {$line}\n" . substr($contents, strlen(self::PHP_OPEN_TAG_LINE)));
    }

    private static function extensionOf(string $path): string
    {
        $fileName = basename($path);
        $dot = strrpos($fileName, '.');

        return $dot === false || $dot === 0 ? '' : substr($fileName, $dot);
    }
}
